    kegelsatz: { kind: "grundlegend", reason: "Ausgangspunkt des Minimalmodellprogramms in höherer Dimension." },
    enrkod: { kind: "grundlegend", reason: "Die vollständige Übersicht über die algebraischen Flächen, an der sich die höherdimensionale Klassifikation orientiert." },
